private static boolean dfs(int n, int[] current, int[] end, int[][] paths, boolean[] visited) {
    int currentIndex = current[0] * n + current[1];
    if (visited[currentIndex]) {
        return false;
    }
    if (current[0] == end[0] && current[1] == end[1]) {
        return true;
    }
    visited[currentIndex] = true;

    for (int[] path : paths) {
        if (path[0] == currentIndex && path[2] == 1) {
            if (dfs(n, new int[]{path[1] / n, path[1] % n}, end, paths, visited)) {
                return true;
            }
        } else if (path[1] == currentIndex && path[2] == 1) {
            if (dfs(n, new int[]{path[0] / n, path[0] % n}, end, paths, visited)) {
                return true;
            }
        }
    }

    return false;
}

