public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    int[] remainderCounts = new int[k];
    for (int num : arr) {
        int remainder = (num % k + k) % k; // Ensure non-negative remainder
        remainderCounts[remainder]++;
    }

    if (remainderCounts[0] % 2 != 0) {
        return false;
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create an adjacency list to represent the tree
    List<List<Integer>> tree = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    // Use DFS to calculate the minimum time to collect all apples
    return dfs(0, -1, tree, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> tree, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : tree.get(node)) {
        if (neighbor == parent) continue; // Skip the parent node
        int subTime = dfs(neighbor, node, tree, hasApple);
        if (subTime > 0 || hasApple[neighbor]) {
            time += subTime + 2; // Each valid path adds 2 units of time (to and from the node)
        }
    }
    return time;
}

