    }

    return backtrack(A, 0, new HashMap<>(), dp);
}

private static int backtrack(int[] A, int start, Map<Integer, Integer> frequency, int[][] dp) {
    int n = A.length;
    if (start == n - 1) {
        return 1;
    }

    if (dp[start][frequencyHash(frequency)] != -1) {
        return dp[start][frequencyHash(frequency)];
    }

    int result = 0;
    for (int i = start + 1; i < n; i++) {
        if (isPerfectSquare(A[start] + A[i])) {
            int key = A[i];
            frequency.put(key, frequency.getOrDefault(key, 0) + 1);

            result += backtrack(A, i, frequency, dp);

            frequency.put(key, frequency.get(key) - 1);
            if (frequency.get(key) == 0) {
                frequency.remove(key);
            }
        }
    }

    dp[start][frequencyHash(frequency)] = result;
    return result;
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

private static int frequencyHash(Map<Integer, Integer> frequency) {
    int hash = 0;
    for (Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        hash = hash * 31 + entry.getKey() * 31 + entry.getValue();
    }
    return hash;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;

    for (int i = 0; i <= n; i++) {
        while (!stack.isEmpty() && (i == n || heights[i] < heights[stack.peek()])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    boolean up = true;

    int row = 0, col = 0;
    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];

        if (up) {
            if (col == cols - 1) {
                row++;
                up = false;
            } else if (row == 0) {
                col++;
                up = false;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == rows - 1) {
                col++;
                up = true;
            } else if (col == 0) {
                row++;
                up = true;
            } else {
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that is smaller than the digit next to it from the right
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (not possible to find a greater number)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i) which is greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)th position
    Arrays.sort(digits, i + 1, length);

    // Convert the digits back to a number
    int result = Integer.parseInt(new String(digits));

    // Check if the result is greater than the original number
    if (result > n) {
        return result;
    } else {
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    List<String> result = new ArrayList<>();
    HashSet<Character> set = new HashSet<>();
    set.add('0');
    set.add('1');
    set.add('6');
    set.add('8');
    set.add('9');
    helper(result, new char[n], set, 0, n - 1);
    return result;
}

private static void helper(List<String> result, char[] current, HashSet<Character> set, int left, int right) {
    if (left > right) {
        result.add(String.copyValueOf(current));
        return;
    }
    if (left == right) {
        for (char c : set) {
            if (c != '0' || left != 0) {
                current[left] = c;
                result.add(String.copyValueOf(current));
            }
        }
        return;
    }
    for (char c : set) {
        if (c == '6') {
            current[left] = '6';
            current[right] = '9';
        } else if (c == '9') {
            current[left] = '9';
            current[right] = '6';
        } else {
            current[left] = c;
            current[right] = c;
        }
        helper(result, current, set, left + 1, right - 1);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Calculate the area of the triangle formed by the points using the determinant method
    int area = p1[0] * (p2[1] - p3[1]) + p2[0] * (p3[1] - p1[1]) + p3[0] * (p1[1] - p2[1]);

    // If the area is zero, the points are collinear and do not form a boomerang
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            i2++;
            nextMultipleOf2 = uglyNumbers[i2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            i3++;
            nextMultipleOf3 = uglyNumbers[i3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            i5++;
            nextMultipleOf5 = uglyNumbers[i5] * 5;
        }
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
        } else {
            maxEnergy = Math.max(maxEnergy, currentEnergy);
            currentEnergy = 1;
        }
    }

    maxEnergy = Math.max(maxEnergy, currentEnergy);

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        result.add(i);
    }
    result.sort((a, b) -> a.toString().compareTo(b.toString()));
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    Map<Integer, Integer> frequencyMap = new HashMap<>();
    for (int num : nums) {
        frequencyMap.put(num, frequencyMap.getOrDefault(num, 0) + 1);
    }

    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }

    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (String word : words) {
        result.append(new StringBuilder(word).reverse()).append(" ");
    }

    if (result.length() > 0) {
        result.setLength(result.length() - 1);
    }

    return result.toString();
}
